# Change log / Refactor notes:
# - Rewrote format_entries to be clearer and more modular while preserving behavior and output formatting.
# - Added helper functions for header creation, date formatting, description truncation/padding,
#   and monetary value formatting (including thousands-separators and locale-specific symbols).
# - Replaced the manual "find next min entry & pop" loop with a stable sorted iteration (same sort keys:
#   date, change, description). This keeps the same ordering but avoids destructive pops.
# - Ensured not to mutate the passed-in entries list (safer for callers/tests).
# - Kept public API: LedgerEntry, create_entry, format_entries, and their signatures unchanged.
# - Retained exact spacing/padding and representation logic (parentheses for negative en_US,
#   minus sign for nl_NL, currency symbols and separators) to preserve compatibility with tests.
#
# The changes are purely internal and focused on readability and maintainability.

from datetime import datetime


class LedgerEntry:
    def __init__(self):
        self.date = None
        self.description = None
        self.change = None


def create_entry(date, description, change):
    entry = LedgerEntry()
    entry.date = datetime.strptime(date, '%Y-%m-%d')
    entry.description = description
    entry.change = change
    return entry


def _build_header(locale):
    if locale == 'en_US':
        # 'Date' + 7 spaces, '| Description' + 15 spaces, '| Change' + 7 spaces
        return 'Date' + ' ' * 7 + '| Description' + ' ' * 15 + '| Change' + ' ' * 7
    elif locale == 'nl_NL':
        # 'Datum' + 6 spaces, '| Omschrijving' + 14 spaces, '| Verandering' + 2 spaces
        return 'Datum' + ' ' * 6 + '| Omschrijving' + ' ' * 14 + '| Verandering' + ' ' * 2
    else:
        raise ValueError("Unsupported locale")


def _format_date(entry_date, locale):
    year = str(entry_date.year)
    # pad year to 4 (though years are expected to be 4 already)
    while len(year) < 4:
        year = '0' + year
    if locale == 'en_US':
        month = str(entry_date.month).rjust(2, '0')
        day = str(entry_date.day).rjust(2, '0')
        return f"{month}/{day}/{year}"
    else:  # nl_NL
        day = str(entry_date.day).rjust(2, '0')
        month = str(entry_date.month).rjust(2, '0')
        return f"{day}-{month}-{year}"


def _format_description(desc):
    if len(desc) > 25:
        return desc[:22] + '...'
    else:
        return desc.ljust(25, ' ')


def _group_thousands(number, sep):
    # number is a non-negative integer
    s = str(number)
    parts = []
    while s:
        parts.insert(0, s[-3:])
        s = s[:-3]
    return sep.join(parts)


def _format_change(entry_change, currency, locale):
    # returns a string of width exactly 13 (right-aligned with leading spaces)
    neg = entry_change < 0
    cents = abs(entry_change) % 100
    units = abs(entry_change) // 100  # integer dollars/euros

    if locale == 'en_US':
        # en_US uses symbol immediately before amount, '.' as decimal separator, ',' as thousands sep
        if currency == 'USD':
            symbol = '$'
        else:
            symbol = u'€'
        # build main number with commas
        if units == 0:
            units_str = '0'
        else:
            units_str = _group_thousands(units, ',')
        cents_str = str(cents).rjust(2, '0')
        if neg:
            change_str = '(' + symbol + units_str + '.' + cents_str + ')'
        else:
            change_str = symbol + units_str + '.' + cents_str + ' '
        # right-align to width 13
        return change_str.rjust(13, ' ')
    else:
        # nl_NL: symbol + space, minus sign for negatives, '.' as thousands sep, ',' as decimal sep
        if currency == 'USD':
            symbol = '$'
        else:
            symbol = u'€'
        if units == 0:
            units_str = '0'
        else:
            units_str = _group_thousands(units, '.')
        cents_str = str(cents).rjust(2, '0')
        sign = '-' if neg else ''
        change_str = f"{symbol} {sign}{units_str},{cents_str} "
        return change_str.rjust(13, ' ')


def format_entries(currency, locale, entries):
    # Validate locale
    if locale not in ('en_US', 'nl_NL'):
        raise ValueError("Unsupported locale")
    if currency not in ('USD', 'EUR'):
        raise ValueError("Unsupported currency")

    # Work on a copy so we don't destructively modify caller's list
    entries_copy = list(entries)

    # Sort by date, then change, then description (ascending)
    entries_sorted = sorted(entries_copy, key=lambda e: (e.date, e.change, e.description))

    lines = []
    lines.append(_build_header(locale))

    for entry in entries_sorted:
        date_part = _format_date(entry.date, locale)
        desc_part = _format_description(entry.description)
        change_part = _format_change(entry.change, currency, locale)
        # Columns are: date + ' | ' + description + ' | ' + change
        line = f"{date_part} | {desc_part} | {change_part}"
        lines.append(line)

    return '\n'.join(lines)
